  "description": "A Mediterranean cousin of our native madrone with glossy evergreen leaves, shreddy red-brown bark, and the novelty of white bell flowers and red strawberry-like fruit at the same time in fall. Drought tolerant and much easier to grow than madrone. Pairs with manzanita, rockrose, ceanothus, ornamental grasses and kinnikinnick.",
