  "description": "An unusual, sculptural shrub with cinnamon-brown branches tipped in silky silver buds all winter that open into fragrant yellow-cream pompoms in late winter, followed by lush, tropical-looking leaves. It's a guaranteed conversation piece. Pair with hellebores, sweet box, witch hazel, and ferns for a winter-fragrance corner.",
