  "description": "An eastern US native with drooping sprays of white flowers in midsummer and some of the most reliable scarlet fall color of any tree in Seattle. The seed sprays hang on into autumn and look like lace over the red leaves. Pair with blueberries, evergreen huckleberry, and salal, which like the same acidic soil.",
